import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { createContractProcedureBuilder } from "../errors";

const contractProcedure = createContractProcedureBuilder();

const requestEmailVerificationInputSchema = z
  .object({
    email: z
      .string()
      .trim()
      .toLowerCase()
      .min(1, "Email is required")
      .email("Enter a valid email address"),
  })
  .strict();

const requestEmailVerificationOutputSchema = z
  .object({
    ok: z.literal(true),
  })
  .strict();

export const authContract = {
  requestEmailVerification: contractProcedure
    .input(requestEmailVerificationInputSchema)
    .output(requestEmailVerificationOutputSchema),
} as const;

export type AuthContract = typeof authContract;
export type AuthContractInputs = InferContractRouterInputs<AuthContract>;
export type AuthContractOutputs = InferContractRouterOutputs<AuthContract>;

export type RequestEmailVerificationInput =
  AuthContractInputs["requestEmailVerification"];
export type RequestEmailVerificationOutput =
  AuthContractOutputs["requestEmailVerification"];
